/* Local UI lock: prevents accidental timer edits; does not lock Android itself. */
(()=>{
const el=id=>document.getElementById(id),KEY='focus-dial-lock-v2';
let prefs={method:'drag',credential:null,active:false};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved){prefs.active=saved.active===true;if(['drag','pin','pattern'].includes(saved.method)&& (saved.method==='drag'||saved.credential?.hash&&saved.credential?.salt)){prefs.method=saved.method;prefs.credential=saved.credential||null}}}catch{}
let locked=false,lastRunning=running,revealTimer,mode='unlock',draftMethod='drag',firstEntry=null,pattern=[],drawing=false,busy=false,attempts=0,cooldownUntil=0,cooldownTimer;
const dialog=el('lock-dialog');
const lockIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>';
el('lock-now').innerHTML=lockIcon;
const section=document.createElement('section');section.className='lock-settings';section.innerHTML='<h3>화면 잠금</h3><label for="lock-method">잠금 해제 방법</label><select id="lock-method"><option value="drag">오른쪽으로 드래그</option><option value="pin">3자리 비밀번호</option><option value="pattern">패턴 그리기</option></select><button type="button" id="change-secret" hidden>비밀번호 변경</button><p id="lock-method-status" role="status"></p><p>시작하면 타이머만 표시됩니다. 화면을 누르면 잠금 해제 버튼이 나타나요. 잠금 정보는 이 기기에 저장됩니다.</p>';
el('settings-dialog').querySelector('form').append(section);
function save(){try{localStorage.setItem(KEY,JSON.stringify(prefs));return true}catch{el('lock-method-status').textContent='이 브라우저는 저장을 허용하지 않아, 창을 닫으면 설정이 사라질 수 있어요.';return false}}
const names={drag:'드래그',pin:'3자리 비밀번호',pattern:'패턴'};
function syncSettings(){el('lock-method').value=prefs.method;el('change-secret').hidden=prefs.method==='drag';el('change-secret').textContent=prefs.method==='pattern'?'패턴 변경':'비밀번호 변경';el('lock-method-status').textContent=`현재: ${names[prefs.method]}${prefs.method==='pattern'?'으로':'로'} 잠금 해제`;}
function reveal(){if(!locked)return;el('lock-bar').hidden=false;clearTimeout(revealTimer);revealTimer=setTimeout(()=>{if(!dialog.open)el('lock-bar').hidden=true},5000)}
function lockScreen(revealNow=false){if(dialog.open||el('settings-dialog').open)return;locked=true;prefs.active=true;document.body.classList.add('focus-mode');el('focus-shield').hidden=false;el('lock-bar').hidden=true;el('dial').setAttribute('tabindex','-1');el('dial').setAttribute('role','img');el('dial').setAttribute('aria-label','남은 시간을 보여주는 다이얼');el('focus-shield').focus({preventScroll:true});save();if(revealNow)reveal()}
function unlockScreen(){locked=false;prefs.active=false;document.body.classList.remove('focus-mode');el('focus-shield').hidden=true;el('lock-bar').hidden=true;el('dial').setAttribute('tabindex','0');el('dial').setAttribute('role','slider');el('dial').setAttribute('aria-label','타이머 시간, 방향키로 1분씩 조절');clearTimeout(revealTimer);save();if(dialog.open)dialog.close();el('start').focus({preventScroll:true})}
window.isScreenLocked=()=>locked;
el('lock-now').onclick=()=>lockScreen(true);el('focus-shield').onclick=reveal;el('unlock-open').onclick=()=>openDialog('unlock',prefs.method);
window.addEventListener('timerstate',e=>{if(e.detail.running&&!lastRunning)lockScreen();lastRunning=e.detail.running;});
async function hash(value,salt){const bytes=new TextEncoder().encode(`focus-dial:${salt}:${value}`);return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('')}
function clearEntry(){el('lock-pin').value='';pattern=[];drawPattern();el('unlock-slider').value=0;}
function drawPattern(){el('pattern-line').setAttribute('points',pattern.map(n=>`${50+(n%3)*100},${50+Math.floor(n/3)*100}`).join(' '));el('pattern-grid').querySelectorAll('.pattern-node').forEach((node,i)=>{node.classList.toggle('active',pattern.includes(i));node.setAttribute('aria-pressed',String(pattern.includes(i)))})}
function addNode(n){if(pattern.includes(n))return;const last=pattern.at(-1);if(last!==undefined){const x1=last%3,y1=Math.floor(last/3),x2=n%3,y2=Math.floor(n/3);if((Math.abs(x2-x1)===2&&y1===y2)||(Math.abs(y2-y1)===2&&x1===x2)||(Math.abs(x2-x1)===2&&Math.abs(y2-y1)===2)){const middle=((y1+y2)/2)*3+(x1+x2)/2;if(!pattern.includes(middle))pattern.push(middle)}}pattern.push(n);el('lock-error').textContent='';drawPattern()}
const grid=el('pattern-grid');for(let i=0;i<9;i++){const b=document.createElement('button');b.type='button';b.className='pattern-node';b.style.left=`${(i%3+.5)/3*100}%`;b.style.top=`${(Math.floor(i/3)+.5)/3*100}%`;b.setAttribute('aria-label',`패턴 점 ${i+1}`);b.setAttribute('aria-pressed','false');b.onclick=e=>{if(e.detail===0)addNode(i)};grid.append(b)}
function hitNode(e){const r=grid.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;const col=Math.floor(x*3),row=Math.floor(y*3);if(col<0||col>2||row<0||row>2)return;const cx=(col+.5)/3,cy=(row+.5)/3;if(Math.hypot(x-cx,y-cy)<.12)addNode(row*3+col)}
grid.addEventListener('pointerdown',e=>{if(busy)return;e.preventDefault();drawing=true;grid.setPointerCapture(e.pointerId);hitNode(e)});grid.addEventListener('pointermove',e=>{if(drawing)hitNode(e)});for(const event of['pointerup','pointercancel'])grid.addEventListener(event,()=>drawing=false);
el('pattern-clear').onclick=()=>{pattern=[];drawPattern();el('lock-error').textContent=''};
function configureEntry(){el('pin-entry').hidden=draftMethod!=='pin';el('pattern-entry').hidden=draftMethod!=='pattern';el('drag-entry').hidden=draftMethod!=='drag';el('lock-submit').hidden=draftMethod==='drag';el('lock-title').textContent=mode==='unlock'?'잠금 해제':`${names[draftMethod]} ${firstEntry?'확인':'설정'}`;el('lock-description').textContent=mode==='unlock'?(draftMethod==='drag'?'화면 잠금을 풀고 조작 화면으로 돌아갑니다.':draftMethod==='pin'?'설정한 숫자 3자리를 입력하세요.':'설정한 패턴을 이어 그린 뒤 확인을 눌러주세요.'):firstEntry?'확인을 위해 같은 내용을 한 번 더 입력하세요.':draftMethod==='pin'?'사용할 숫자 3자리를 입력하세요.':'점 4개 이상을 이어 패턴을 만든 뒤 확인을 눌러주세요.';}
function openDialog(nextMode,method){mode=nextMode;draftMethod=method;firstEntry=null;busy=false;el('lock-submit').disabled=false;clearEntry();el('lock-error').textContent='';configureEntry();if(el('settings-dialog').open)el('settings-dialog').close();dialog.showModal();if(method==='pin')el('lock-pin').focus();if(mode==='unlock'&&cooldownUntil>Date.now())showCooldown()}
function cancel(){if(busy)return;dialog.close();clearEntry();firstEntry=null;syncSettings();if(mode==='setup')el('settings-dialog').showModal();else reveal()}
el('lock-cancel').onclick=cancel;dialog.addEventListener('cancel',e=>{e.preventDefault();cancel()});dialog.addEventListener('close',()=>{clearEntry();firstEntry=null;clearInterval(cooldownTimer)});
el('lock-method').onchange=e=>{const method=e.target.value;if(method==='drag'){prefs.method='drag';prefs.credential=null;save();syncSettings()}else openDialog('setup',method)};
el('change-secret').onclick=()=>openDialog('setup',prefs.method);
el('lock-pin').addEventListener('input',()=>{el('lock-pin').value=el('lock-pin').value.replace(/\D/g,'').slice(0,3);el('lock-error').textContent=''});
document.querySelectorAll('[data-digit]').forEach(b=>b.onclick=()=>{if(el('lock-pin').value.length<3)el('lock-pin').value+=b.dataset.digit;el('lock-error').textContent=''});el('pin-clear').onclick=()=>el('lock-pin').value='';el('pin-back').onclick=()=>el('lock-pin').value=el('lock-pin').value.slice(0,-1);
function showCooldown(){clearInterval(cooldownTimer);const update=()=>{const s=Math.ceil((cooldownUntil-Date.now())/1000);el('lock-submit').disabled=s>0;el('lock-error').textContent=s>0?`잠시 기다려 주세요. ${s}초 후 다시 시도할 수 있어요.`:'';if(s<=0)clearInterval(cooldownTimer)};update();cooldownTimer=setInterval(update,500)}
el('lock-form').addEventListener('submit',async e=>{e.preventDefault();if(busy||draftMethod==='drag'||cooldownUntil>Date.now()&&mode==='unlock')return;const value=draftMethod==='pin'?el('lock-pin').value:pattern.join('-');if(draftMethod==='pin'&&!/^\d{3}$/.test(value)){el('lock-error').textContent='숫자 3자리를 입력해 주세요.';return}if(draftMethod==='pattern'&&pattern.length<4){el('lock-error').textContent='점 4개 이상을 이어주세요.';return}busy=true;el('lock-submit').disabled=true;try{if(mode==='setup'){if(firstEntry===null){firstEntry=value;clearEntry();configureEntry();el('lock-error').textContent='';if(draftMethod==='pin')el('lock-pin').focus()}else if(firstEntry!==value){clearEntry();el('lock-error').textContent='처음 입력한 내용과 달라요. 같은 내용을 다시 입력해 주세요.'}else{const salt=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');prefs.method=draftMethod;prefs.credential={salt,hash:await hash(value,salt)};save();syncSettings();dialog.close();el('settings-dialog').showModal()}}else{const valid=await hash(value,prefs.credential.salt)===prefs.credential.hash;if(valid){attempts=0;unlockScreen()}else{attempts++;clearEntry();el('lock-error').textContent='일치하지 않아요. 다시 입력해 주세요.';if(attempts>=5){attempts=0;cooldownUntil=Date.now()+15000;showCooldown()}}}}catch{el('lock-error').textContent='잠금 정보를 처리하지 못했어요. HTTPS 연결에서 다시 시도해 주세요.'}finally{busy=false;if(cooldownUntil<=Date.now()||mode==='setup')el('lock-submit').disabled=false}});
let slideStarted=false;el('unlock-slider').addEventListener('pointerdown',e=>{const r=el('unlock-slider').getBoundingClientRect();slideStarted=e.clientX-r.left<=65&&Number(el('unlock-slider').value)<=5;if(!slideStarted)e.preventDefault()});el('unlock-slider').addEventListener('input',()=>{if(slideStarted&&Number(el('unlock-slider').value)>=98){slideStarted=false;unlockScreen()}});for(const event of['pointerup','pointercancel'])el('unlock-slider').addEventListener(event,()=>{slideStarted=false;el('unlock-slider').value=0});el('unlock-slider').addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='End')slideStarted=true});el('unlock-slider').addEventListener('keyup',()=>{slideStarted=false;if(dialog.open)el('unlock-slider').value=0});
syncSettings();if(prefs.active||running)lockScreen();
})();
